CREATE TABLE IF NOT EXISTS seat_bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,seat_id BIGINT NOT NULL,classroom_id BIGINT NOT NULL,reservation_id BIGINT NULL,start_time DATETIME(3) NOT NULL,end_time DATETIME(3) NOT NULL,status VARCHAR(20) NOT NULL,created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3),cancelled_at DATETIME(3) NULL,hold_expires_at DATETIME(3) NOT NULL,INDEX(user_id),INDEX(status,start_time));
CREATE TABLE IF NOT EXISTS seat_checkins (id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL UNIQUE,checkin_method VARCHAR(20) NOT NULL,checkin_time DATETIME(3) NOT NULL,FOREIGN KEY(booking_id) REFERENCES seat_bookings(id));
CREATE TABLE IF NOT EXISTS booking_violations (id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,booking_id BIGINT NOT NULL UNIQUE,violation_type VARCHAR(30) NOT NULL,occurred_at DATETIME(3) NOT NULL,FOREIGN KEY(booking_id) REFERENCES seat_bookings(id));
CREATE TABLE IF NOT EXISTS booking_settings (setting_key VARCHAR(50) PRIMARY KEY,setting_value VARCHAR(255) NOT NULL,updated_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
INSERT IGNORE INTO booking_settings(setting_key,setting_value) VALUES ('max_booking_hours','4');
CREATE TABLE IF NOT EXISTS event_outbox (id BIGINT PRIMARY KEY AUTO_INCREMENT,payload JSON NOT NULL,sent BOOLEAN NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS notification_outbox (id BIGINT PRIMARY KEY AUTO_INCREMENT,booking_id BIGINT NOT NULL,kind VARCHAR(40) NOT NULL,payload JSON NOT NULL,sent BOOLEAN NOT NULL DEFAULT 0,UNIQUE(booking_id,kind));
